package gen

import (
	"fmt"
	"strconv"
	"strings"
)

// header starts every generated file.
const header = "// Code generated by herdr-api-gen. DO NOT EDIT.\n"

// code collects generated Go source.
type code struct {
	b strings.Builder
}

func (c *code) printf(format string, args ...any) {
	fmt.Fprintf(&c.b, format, args...)
}

func (c *code) line(s string) {
	c.b.WriteString(s)
	c.b.WriteString("\n")
}

func (c *code) blank() {
	c.b.WriteString("\n")
}

func (c *code) String() string {
	return c.b.String()
}

// file starts a generated file with its package clause and imports.
func newFile(pkg string, imports ...string) *code {
	c := &code{}
	c.line(header)
	c.printf("package %s\n", pkg)
	switch len(imports) {
	case 0:
	case 1:
		c.blank()
		c.printf("import %q\n", imports[0])
	default:
		c.blank()
		c.line("import (")
		for _, name := range imports {
			c.printf("\t%q\n", name)
		}
		c.line(")")
	}
	return c
}

// doc writes a comment block, wrapping the schema description at a width that
// keeps the output stable.
func (c *code) doc(lines ...string) {
	for _, line := range lines {
		if line == "" {
			c.line("//")
			continue
		}
		for _, wrapped := range wrap(line, 72) {
			c.printf("// %s\n", wrapped)
		}
	}
}

// wrap breaks text into lines of at most width columns, collapsing the
// whitespace the schema descriptions carry.
func wrap(text string, width int) []string {
	words := strings.Fields(text)
	if len(words) == 0 {
		return nil
	}
	var lines []string
	current := words[0]
	for _, word := range words[1:] {
		if len(current)+1+len(word) > width {
			lines = append(lines, current)
			current = word
			continue
		}
		current += " " + word
	}
	return append(lines, current)
}

// tag renders the struct tag of a field.
func (f *Field) tag() string {
	name := f.JSON
	if f.Optional {
		name += ",omitzero"
	} else if f.OmitEmpty {
		name += ",omitempty"
	}
	return "`json:" + strconv.Quote(name) + "`"
}

// emitType writes one named type with the methods that belong to it.
func emitType(c *code, t *Type, clones *cloneEmitter) {
	switch t.Kind {
	case KindEnum:
		emitEnum(c, t)
	case KindUnion:
		emitUnion(c, t, clones)
	default:
		emitStruct(c, t, clones)
	}
}

func emitEnum(c *code, t *Type) {
	if t.Doc != "" {
		c.doc(t.Doc)
	}
	c.printf("type %s string\n", t.Name)
	c.blank()
	c.printf("// %s values.\n", t.Name)
	c.line("const (")
	for _, v := range t.Values {
		c.printf("\t%s %s = %q\n", v.Name, t.Name, v.Value)
	}
	c.line(")")
}

func emitUnion(c *code, t *Type, clones *cloneEmitter) {
	c.doc(fmt.Sprintf("%s is a union of the types below, selected by the %q field.",
		t.Name, t.Discriminator),
		"",
		"Each variant satisfies the interface as a value, and decoding produces",
		"values too, so one spelling works whether a union value is built here",
		"or read out of a response.")
	if t.Doc != "" {
		c.doc("", t.Doc)
	}
	c.printf("type %s interface {\n", t.Name)
	c.printf("\tis%s()\n", t.Name)
	c.line("}")
	clones.emitUnion(c, t)
	c.blank()
	emitUnionDecoder(c, t)
}

func emitUnionDecoder(c *code, t *Type) {
	c.printf("func decode%s(data []byte) (%s, error) {\n", t.Name, t.Name)
	c.line("\tvar head struct {")
	c.printf("\t\tTag string `json:%q`\n", t.Discriminator)
	c.line("\t}")
	c.line("\tif err := json.Unmarshal(data, &head); err != nil {")
	c.line("\t\treturn nil, err")
	c.line("\t}")
	c.line("\tswitch head.Tag {")
	for _, variant := range t.Variants {
		c.printf("\tcase %q:\n", variant.TagValue)
		c.printf("\t\tvar value %s\n", variant.Name)
		c.line("\t\tif err := json.Unmarshal(data, &value); err != nil {")
		c.line("\t\t\treturn nil, err")
		c.line("\t\t}")
		c.line("\t\treturn value, nil")
	}
	c.line("\t}")
	c.printf("\treturn nil, fmt.Errorf(\"herdr: unknown %s %%q\", head.Tag)\n", t.Name)
	c.line("}")
}

func emitStruct(c *code, t *Type, clones *cloneEmitter) {
	switch {
	case t.ResultTag != "":
		c.doc(fmt.Sprintf("%s is the %q result.", t.Name, t.ResultTag))
		if t.Doc != "" {
			c.doc("", t.Doc)
		}
	case t.EventName != "":
		c.doc(fmt.Sprintf("%s is the %q event payload.", t.Name, t.EventName))
		if t.Doc != "" {
			c.doc("", t.Doc)
		}
	case t.UnionName != "":
		c.doc(fmt.Sprintf("%s is the %q variant of %s.", t.Name, t.TagValue, t.UnionName))
		if t.Doc != "" {
			c.doc("", t.Doc)
		}
	case t.Doc != "":
		c.doc(t.Doc)
	}
	if len(t.Fields) == 0 {
		c.printf("type %s struct{}\n", t.Name)
	} else {
		c.printf("type %s struct {\n", t.Name)
		for i, f := range t.Fields {
			if f.Doc != "" {
				if i > 0 {
					c.blank()
				}
				for _, wrapped := range wrap(f.Doc, 68) {
					c.printf("\t// %s\n", wrapped)
				}
			}
			c.printf("\t%s %s %s\n", f.Name, f.Type, f.tag())
		}
		c.line("}")
	}
	if clones.seen[t.Name] {
		c.blank()
		clones.emitMethod(c, t)
	}
	if t.UnionName != "" {
		c.blank()
		c.printf("func (%s) is%s() {}\n", t.Name, t.UnionName)
	}
	if t.ResultTag != "" {
		c.blank()
		c.printf("// ResultType returns %q.\n", t.ResultTag)
		c.printf("func (%s) ResultType() string { return %q }\n", t.Name, t.ResultTag)
	}
	if t.EventName != "" {
		c.blank()
		c.printf("// EventName returns %q.\n", t.EventName)
		c.printf("func (%s) EventName() string { return %q }\n", t.Name, t.EventName)
	}
	if t.TagField != "" {
		c.blank()
		emitMarshal(c, t)
	}
	if t.NeedsUnmarshal() {
		c.blank()
		emitUnmarshal(c, t)
	}
}

// emitMarshal writes the MarshalJSON that puts the discriminator back into the
// encoded object.
func emitMarshal(c *code, t *Type) {
	c.printf("// MarshalJSON writes the object with its %q field.\n", t.TagField)
	c.printf("func (v %s) MarshalJSON() ([]byte, error) {\n", t.Name)
	c.printf("\ttype alias %s\n", t.Name)
	c.line("\treturn json.Marshal(struct {")
	c.printf("\t\t%s string `json:%q`\n", pascal(t.TagField), t.TagField)
	c.line("\t\talias")
	c.printf("\t}{%s: %q, alias: alias(v)})\n", pascal(t.TagField), t.TagValue)
	c.line("}")
}

// emitUnmarshal writes the UnmarshalJSON that decodes union-typed fields
// through their variant decoder.
func emitUnmarshal(c *code, t *Type) {
	c.line("// UnmarshalJSON decodes the fields that hold a union value.")
	c.printf("func (v *%s) UnmarshalJSON(data []byte) error {\n", t.Name)
	c.printf("\ttype alias %s\n", t.Name)
	c.line("\tvar aux struct {")
	c.line("\t\talias")
	for _, f := range t.Fields {
		if f.Union == "" {
			continue
		}
		raw := "json.RawMessage"
		if f.UnionSlice && !f.Optional {
			raw = "[]json.RawMessage"
		}
		c.printf("\t\t%s %s %s\n", f.Name, raw, f.tag())
	}
	c.line("\t}")
	c.line("\tif err := json.Unmarshal(data, &aux); err != nil {")
	c.line("\t\treturn err")
	c.line("\t}")
	c.printf("\t*v = %s(aux.alias)\n", t.Name)
	for _, f := range t.Fields {
		if f.Union == "" {
			continue
		}
		if f.Optional {
			c.printf("\tif len(aux.%s) > 0 {\n", f.Name)
			c.printf("\t\tif string(aux.%s) == \"null\" {\n", f.Name)
			c.printf("\t\t\tv.%s = Null[%s]()\n", f.Name, f.ValueType)
			c.line("\t\t} else {")
			if f.UnionSlice {
				c.line("\t\t\tvar items []json.RawMessage")
				c.printf("\t\t\tif err := json.Unmarshal(aux.%s, &items); err != nil {\n", f.Name)
				c.line("\t\t\t\treturn err")
				c.line("\t\t\t}")
				c.printf("\t\t\tdecodedItems := make(%s, 0, len(items))\n", f.ValueType)
				c.line("\t\t\tfor _, item := range items {")
				c.printf("\t\t\t\tdecoded, err := decode%s(item)\n", f.Union)
				c.line("\t\t\t\tif err != nil {")
				c.line("\t\t\t\t\treturn err")
				c.line("\t\t\t\t}")
				c.line("\t\t\t\tdecodedItems = append(decodedItems, decoded)")
				c.line("\t\t\t}")
				c.printf("\t\t\tv.%s = Some(decodedItems)\n", f.Name)
			} else {
				c.printf("\t\t\tdecoded, err := decode%s(aux.%s)\n", f.Union, f.Name)
				c.line("\t\t\tif err != nil {")
				c.line("\t\t\t\treturn err")
				c.line("\t\t\t}")
				c.printf("\t\t\tv.%s = Some(decoded)\n", f.Name)
			}
			c.line("\t\t}")
			c.line("\t}")
			continue
		}
		if f.UnionSlice {
			c.printf("\tif len(aux.%s) > 0 {\n", f.Name)
			c.printf("\t\tv.%s = make(%s, 0, len(aux.%s))\n", f.Name, f.Type, f.Name)
			c.printf("\t\tfor _, item := range aux.%s {\n", f.Name)
			c.printf("\t\t\tdecoded, err := decode%s(item)\n", f.Union)
			c.line("\t\t\tif err != nil {")
			c.line("\t\t\t\treturn err")
			c.line("\t\t\t}")
			c.printf("\t\t\tv.%s = append(v.%s, decoded)\n", f.Name, f.Name)
			c.line("\t\t}")
			c.line("\t}")
			continue
		}
		c.printf("\tif len(aux.%s) > 0 && string(aux.%s) != \"null\" {\n", f.Name, f.Name)
		c.printf("\t\tdecoded, err := decode%s(aux.%s)\n", f.Union, f.Name)
		c.line("\t\tif err != nil {")
		c.line("\t\t\treturn err")
		c.line("\t\t}")
		c.printf("\t\tv.%s = decoded\n", f.Name)
		c.line("\t}")
	}
	c.line("\treturn nil")
	c.line("}")
}
